WITH marked AS (SELECT user_id, minute, CASE WHEN LAG(minute) OVER (PARTITION BY user_id ORDER BY minute) IS NULL OR minute-LAG(minute) OVER (PARTITION BY user_id ORDER BY minute)>30 THEN 1 ELSE 0 END AS starts FROM events), numbered AS (SELECT user_id, minute, SUM(starts) OVER (PARTITION BY user_id ORDER BY minute) AS session_no FROM marked) SELECT user_id, session_no, MIN(minute) AS start_minute, MAX(minute) AS end_minute FROM numbered GROUP BY user_id, session_no ORDER BY user_id, session_no;
